<script setup lang="ts">
import {ElMessage} from 'element-plus';
const props=defineProps<{summaryId:string;slideKey:string}>();const {locale}=useI18n();const api=useViewerApiFetch();const beta=useAnnualBeta();const open=ref(false);const kind=ref<'issue'|'survey'>('issue');const category=ref('number');const expectedValue=ref('');const comment=ref('');const busy=ref(false);const error=ref('');const answers=reactive({start:'',auth:'',binding:'',incorrect:'',suspectPage:'',resembles:3,memorablePage:'',share:''});
const ja=computed(()=>locale.value==='ja');const label=computed(()=>ja.value?'データの問題を報告':'数据有问题');
const categories=computed(()=>['number','song_chart','dan','time','missing','subjective_copy','other'].map((value,i)=>({value,label:(ja.value?['数値','曲・譜面','段位','日時','内容の不足','表現が自分に合わない','その他']:['数字不对','歌曲/谱面不对','段位不对','时间不对','内容缺失','描述感觉不符合','其他'])[i]})));
const questions=computed(()=>[
 ['start',ja.value?'始め方は分かりましたか？':'是否顺利理解如何开始体验？'],['auth',ja.value?'登録・ログインで困ったこと':'注册/登录是否遇到困难？'],['binding',ja.value?'連携で分かりにくかったところ':'绑定流程哪里最难理解？'],['incorrect',ja.value?'明らかなデータの誤りはありましたか？':'是否发现明确错误数据？'],['suspectPage',ja.value?'正確さが気になったページ':'哪一页最怀疑准确性？'],['memorablePage',ja.value?'印象に残ったページ':'最有记忆点的一页？'],['share',ja.value?'正式公開後、画像を共有したいですか？':'正式开放后是否愿意分享 Poster？']]);
const show=(value:'issue'|'survey')=>{kind.value=value;error.value='';open.value=true;beta.track('annual_feedback_open',{source:value});};
const submit=async()=>{if(busy.value)return;busy.value=true;error.value='';try{await api('/api/annual-beta/feedback',{method:'POST',headers:{'x-viewer-locale':locale.value},body:{kind:kind.value,summaryId:props.summaryId,slideKey:props.slideKey,category:category.value,expectedValue:expectedValue.value,comment:comment.value,answers}});open.value=false;ElMessage.success(ja.value?'送信しました':'反馈已提交');}catch(e:any){error.value=e?.data?.statusMessage||(ja.value?'送信できませんでした':'提交失败，请重试');}finally{busy.value=false;}};
</script>
<template><div class="beta-feedback"><button type="button" @click="show('issue')">{{label}}</button><button v-if="slideKey==='poster'" type="button" @click="show('survey')">{{ja?'体験アンケート':'体验反馈'}}</button></div><el-dialog class="annual-feedback-dialog" v-model="open" :title="kind==='issue'?label:(ja?'体験アンケート':'体验反馈')" width="min(540px, calc(100vw - 24px))" append-to-body><el-form label-position="top" @submit.prevent="submit"><template v-if="kind==='issue'"><el-form-item :label="ja?'種類':'问题类型'"><el-select v-model="category"><el-option v-for="item in categories" :key="item.value" :value="item.value" :label="item.label"/></el-select></el-form-item><el-form-item :label="ja?'正しいと思う内容':'期望的正确内容'"><el-input v-model="expectedValue" maxlength="300"/></el-form-item><el-form-item :label="ja?'説明':'补充说明'"><el-input v-model="comment" type="textarea" :rows="3" maxlength="1000" show-word-limit/></el-form-item></template><template v-else><el-form-item v-for="[key,text] in questions" :key="key" :label="text"><el-input v-model="(answers as any)[key]" maxlength="300"/></el-form-item><el-form-item :label="ja?'自分の一年らしさ（1–5）':'这份报告像不像你的这一年（1–5）'"><el-rate v-model="answers.resembles"/></el-form-item></template><p v-if="error" role="alert">{{error}}</p><el-button type="primary" native-type="submit" :loading="busy">{{ja?'送信':'提交反馈'}}</el-button></el-form></el-dialog></template>
<style scoped>.beta-feedback{position:fixed;z-index:35;bottom:calc(var(--annual-visual-bottom,0px) + max(10px,env(safe-area-inset-bottom)));left:10px;display:flex;gap:8px}.beta-feedback button{min-height:44px;padding:7px 12px;border:1px solid #3978c844;border-radius:20px;background:#f7fbffee;color:#17365d;cursor:pointer;font-size:12px}.beta-feedback button:focus-visible{outline:3px solid #3978c8;outline-offset:3px}</style>

<style>
.annual-feedback-dialog{margin-top:calc(var(--annual-visual-top,0px) + 12px)!important;max-height:calc(var(--annual-visual-height,100dvh) - 24px);overflow-y:auto;overscroll-behavior:contain;scroll-padding-block:16px}.annual-feedback-dialog input,.annual-feedback-dialog textarea{font-size:16px}
</style>
